# Lliçons del mòdul «Tècniques de magatzem» (1/3): organització, recepció i codificació
L = [
dict(slug='almacen-funciones-tipos-zonas', id='A_almacen', orden=1, codigos=['1.1', '1.2'], fase=1,
 es=dict(titulo='El almacén: funciones, tipos y zonas', objetivo='Explicar para qué sirve un almacén, qué tipos hay y cómo se reparte su espacio.',
  tira=[[('eco','alegria','¡Primer día en el almacén! Dejo las cajas donde haya sitio, ¿no?')],[('nexo','esceptico','¿Y cómo las encontrará el compañero que prepara los pedidos?')],[('nexo','guino','Cada zona tiene su función: recepción, almacenaje, preparación y expedición.')]],
  cos='El <b>almacén</b> guarda la mercancía entre que llega del proveedor y sale hacia el cliente. Sus funciones: <b>recibir</b>, <b>almacenar y conservar</b>, <b>controlar el stock</b>, <b>preparar los pedidos</b> y <b>expedirlos</b>.\n\nTipos: según la mercancía (materias primas, producto acabado, recambios), la función (de fábrica, de distribución, regulador, de tránsito o <i>cross-docking</i>, donde la mercancía casi no se guarda), el régimen (propio, alquilado, de un operador logístico) o el grado de automatización.\n\nZonas habituales: <b>muelles</b> de carga y descarga, <b>recepción y control</b>, <b>almacenaje</b> (estanterías, cámara de frío, zona de peligrosos), <b>preparación de pedidos</b> (picking), <b>expedición</b>, zonas de servicio (oficina, vestuarios, carga de baterías) y pasillos. El <b>flujo</b> puede ser en U (entrada y salida por el mismo lado) o en línea recta (entrada por un lado y salida por el otro).',
  ejemplo='En Palet, el camión del proveedor descarga en el muelle 1, revisas la mercancía en la zona de recepción, la llevas a su estantería y, cuando llega un pedido, la preparas y la dejas en el muelle de expedición.',
  errores=['Dejar mercancía en los pasillos o en la zona de recepción «un momento»: bloquea el flujo y es peligroso.','Confundir la zona de preparación con la de expedición.'],
  test=[('¿Qué almacén guarda la mercancía solo unas horas para repartirla a otros destinos?',['Almacén regulador','Plataforma de cross-docking (de tránsito)','Almacén de materias primas','Almacén de recambios'],1,'La mercancía entra y sale casi sin almacenarse.'),
   ('¿En qué zona se comprueba que la mercancía coincide con el albarán?',['Expedición','Recepción y control','Picking','Zona de servicios'],1,'Antes de ubicarla hay que revisarla.'),
   ('En un almacén con flujo en U…',['La entrada y la salida están en el mismo lado','La entrada y la salida están en lados opuestos','No hay muelles','Solo hay una estantería'],0,'Los muelles de entrada y salida comparten fachada.'),
   ('¿Qué NO es una función del almacén?',['Recibir la mercancía','Conservar la mercancía','Fijar el precio de venta','Preparar los pedidos'],2,'El precio es una decisión comercial.')]),
 ca=dict(titulo='El magatzem: funcions, tipus i zones', objetivo='Explicar per a què serveix un magatzem, quins tipus n\'hi ha i com es reparteix l\'espai.',
  tira=[[('eco','alegria','Primer dia al magatzem! Deixo les caixes on hi hagi lloc, oi?')],[('nexo','esceptico','I com les trobarà el company que prepara les comandes?')],[('nexo','guino','Cada zona té la seva funció: recepció, emmagatzematge, preparació i expedició.')]],
  cos='El <b>magatzem</b> guarda la mercaderia entre que arriba del proveïdor i surt cap al client. Les seves funcions: <b>rebre</b>, <b>emmagatzemar i conservar</b>, <b>controlar l\'estoc</b>, <b>preparar les comandes</b> i <b>expedir-les</b>.\n\nTipus: segons la mercaderia (matèries primeres, producte acabat, recanvis), la funció (de fàbrica, de distribució, regulador, de trànsit o <i>cross-docking</i>, on la mercaderia gairebé no es guarda), el règim (propi, llogat, d\'un operador logístic) o el grau d\'automatització.\n\nZones habituals: <b>molls</b> de càrrega i descàrrega, <b>recepció i control</b>, <b>emmagatzematge</b> (prestatgeries, cambra de fred, zona de perillosos), <b>preparació de comandes</b> (picking), <b>expedició</b>, zones de servei (oficina, vestidors, càrrega de bateries) i passadissos. El <b>flux</b> pot ser en U (entrada i sortida pel mateix costat) o en línia recta (entrada per un costat i sortida per l\'altre).',
  ejemplo='A Palet, el camió del proveïdor descarrega al moll 1, revises la mercaderia a la zona de recepció, la portes a la seva prestatgeria i, quan arriba una comanda, la prepares i la deixes al moll d\'expedició.',
  errores=['Deixar mercaderia als passadissos o a la zona de recepció «un moment»: bloqueja el flux i és perillós.','Confondre la zona de preparació amb la d\'expedició.'],
  test=[('Quin magatzem guarda la mercaderia només unes hores per repartir-la a altres destinacions?',['Magatzem regulador','Plataforma de cross-docking (de trànsit)','Magatzem de matèries primeres','Magatzem de recanvis'],1,'La mercaderia entra i surt gairebé sense emmagatzemar-se.'),
   ('A quina zona es comprova que la mercaderia coincideix amb l\'albarà?',['Expedició','Recepció i control','Picking','Zona de serveis'],1,'Abans d\'ubicar-la cal revisar-la.'),
   ('En un magatzem amb flux en U…',['L\'entrada i la sortida són al mateix costat','L\'entrada i la sortida són a costats oposats','No hi ha molls','Només hi ha una prestatgeria'],0,'Els molls d\'entrada i sortida comparteixen façana.'),
   ('Quina NO és una funció del magatzem?',['Rebre la mercaderia','Conservar la mercaderia','Fixar el preu de venda','Preparar les comandes'],2,'El preu és una decisió comercial.')])),

dict(slug='ubicacion-fija-caotica-codificacion', id='A_ubicacion', orden=2, codigos=['1.4', '1.5'], fase=1,
 es=dict(titulo='Ubicación fija, caótica y códigos de ubicación', objetivo='Leer y usar los códigos de ubicación y comparar la ubicación fija con la caótica.',
  tira=[[('eco','confusion','«A-03-2-B»… ¿Es una matrícula?')],[('nexo','senalando','Pasillo A, módulo 3, nivel 2, posición B. Es la dirección exacta del producto.')],[('eco','alegria','¡Como una calle con número y piso!')]],
  cos='Cada hueco del almacén tiene una <b>dirección</b>: el <b>código de ubicación</b>. Lo más habitual es <b>pasillo - módulo (o columna) - nivel (altura) - posición</b>. Por ejemplo, <b>A-03-2-B</b> es el pasillo A, el módulo 3, el segundo nivel y la posición B. El nivel 1 suele ser el del suelo.\n\nCon <b>ubicación fija</b>, cada producto tiene siempre el mismo sitio: es fácil de aprender, pero se desaprovecha espacio cuando hay poco stock. Con <b>ubicación caótica</b> (o libre), el producto va al primer hueco adecuado y el sistema informático guarda dónde está: aprovecha mejor el espacio, pero sin SGA es imposible encontrar nada. Muchos almacenes combinan las dos: fija para el picking y caótica para las reservas.',
  ejemplo='En Palet, en el nivel de mozo trabajas con ubicación fija y cada producto tiene su código en la estantería. Si dejas el aceite en B-02-1-A en lugar de A-02-1-A, el preparador no lo encontrará.',
  errores=['Dejar el producto en una ubicación «parecida» porque la correcta está ocupada, sin registrarlo.','Usar ubicación caótica sin un sistema que guarde dónde está cada palé.'],
  test=[('En el código B-05-3-A, ¿qué indica el 3?',['El pasillo','El módulo','El nivel (altura)','La posición'],2,'Pasillo-módulo-nivel-posición.'),
   ('¿Qué ventaja tiene la ubicación caótica?',['No necesita informática','Aprovecha mejor el espacio','El personal memoriza mejor dónde está todo','No hay errores nunca'],1,'Cualquier hueco libre sirve.'),
   ('¿Qué necesita imprescindiblemente la ubicación caótica?',['Más personal','Un sistema de gestión de almacén que registre las ubicaciones','Estanterías más altas','Carretillas eléctricas'],1,'Sin registro, nadie sabe dónde está cada producto.'),
   ('Un almacén pequeño con pocas referencias y mucha rotación del personal suele preferir…',['Ubicación fija','Ubicación caótica','No ubicar','Ubicación por colores'],0,'Es más fácil de aprender y no exige un SGA.')]),
 ca=dict(titulo='Ubicació fixa, caòtica i codis d\'ubicació', objetivo='Llegir i fer servir els codis d\'ubicació i comparar la ubicació fixa amb la caòtica.',
  tira=[[('eco','confusion','«A-03-2-B»… És una matrícula?')],[('nexo','senalando','Passadís A, mòdul 3, nivell 2, posició B. És l\'adreça exacta del producte.')],[('eco','alegria','Com un carrer amb número i pis!')]],
  cos='Cada buit del magatzem té una <b>adreça</b>: el <b>codi d\'ubicació</b>. El més habitual és <b>passadís - mòdul (o columna) - nivell (alçada) - posició</b>. Per exemple, <b>A-03-2-B</b> és el passadís A, el mòdul 3, el segon nivell i la posició B. El nivell 1 sol ser el de terra.\n\nAmb <b>ubicació fixa</b>, cada producte té sempre el mateix lloc: és fàcil d\'aprendre, però es desaprofita espai quan hi ha poc estoc. Amb <b>ubicació caòtica</b> (o lliure), el producte va al primer buit adequat i el sistema informàtic guarda on és: aprofita millor l\'espai, però sense SGM és impossible trobar res. Molts magatzems combinen les dues: fixa per al picking i caòtica per a les reserves.',
  ejemplo='A Palet, al nivell de mosso treballes amb ubicació fixa i cada producte té el seu codi a la prestatgeria. Si deixes l\'oli a B-02-1-A en lloc d\'A-02-1-A, el preparador no el trobarà.',
  errores=['Deixar el producte en una ubicació «semblant» perquè la correcta està ocupada, sense registrar-ho.','Fer servir ubicació caòtica sense un sistema que guardi on és cada palet.'],
  test=[('Al codi B-05-3-A, què indica el 3?',['El passadís','El mòdul','El nivell (alçada)','La posició'],2,'Passadís-mòdul-nivell-posició.'),
   ('Quin avantatge té la ubicació caòtica?',['No necessita informàtica','Aprofita millor l\'espai','El personal recorda millor on és tot','No hi ha mai errors'],1,'Qualsevol buit lliure serveix.'),
   ('Què necessita imprescindiblement la ubicació caòtica?',['Més personal','Un sistema de gestió de magatzem que registri les ubicacions','Prestatgeries més altes','Carretons elèctrics'],1,'Sense registre, ningú no sap on és cada producte.'),
   ('Un magatzem petit amb poques referències i molta rotació del personal sol preferir…',['Ubicació fixa','Ubicació caòtica','No ubicar','Ubicació per colors'],0,'És més fàcil d\'aprendre i no exigeix un SGM.')])),

dict(slug='criterios-colocacion', id='A_colocacion', orden=3, codigos=['1.6'], fase=1,
 es=dict(titulo='Dónde colocar cada producto', objetivo='Aplicar los criterios de rotación, peso, volumen, fragilidad y compatibilidad para ubicar la mercancía.',
  tira=[[('eco','alegria','¡Las garrafas de agua arriba del todo, que abajo no caben!')],[('nexo','enfado','¡ECO! Lo pesado, abajo. Y lo que más sale, cerca del muelle y a la altura de la cintura.')],[('eco','verguenza','Vale, vale… bajo las garrafas.')]],
  cos='Para decidir dónde va cada producto se combinan varios criterios:\n\n<b>Rotación</b>: lo que sale más (productos A) va cerca de la zona de expedición y a la altura entre la cintura y los hombros, para recorrer menos y no agacharse. <b>Peso</b>: lo pesado, abajo; lo ligero, arriba. <b>Volumen</b>: lo voluminoso en ubicaciones grandes o en el suelo. <b>Fragilidad</b>: sin nada pesado encima y fuera de los pasos con más tráfico. <b>Compatibilidad</b>: los alimentos separados de los productos de limpieza o químicos, y los peligrosos en su zona. <b>Conservación</b>: lo refrigerado o congelado, en la cámara de frío.',
  ejemplo='En Palet, si colocas el detergente encima de las galletas o el palé de agua en el nivel 3, la jefa te lo hará notar… y si cae, hay rotura y accidente.',
  errores=['Colocar lo pesado en los niveles altos.','Poner productos químicos junto a alimentos.'],
  test=[('¿Dónde debería ir un producto de mucha rotación?',['Al fondo del almacén','Cerca de la expedición y a una altura cómoda','En el nivel más alto','En la cámara de frío'],1,'Así el recorrido y el esfuerzo son menores.'),
   ('¿Qué producto debería ir en el nivel más bajo?',['Paquetes de papel de cocina','Sacos de 25 kg de pienso','Cajas de bombillas','Cajas de pañuelos'],1,'Lo pesado, abajo.'),
   ('¿Qué combinación es incompatible?',['Arroz y pasta','Lejía y galletas','Agua y zumo','Latas y conservas'],1,'Los químicos pueden contaminar los alimentos.'),
   ('¿Qué hay que evitar con los productos frágiles?',['Etiquetarlos','Poner peso encima','Ubicarlos en estantería','Registrarlos'],1,'Se pueden romper.')]),
 ca=dict(titulo='On col·locar cada producte', objetivo='Aplicar els criteris de rotació, pes, volum, fragilitat i compatibilitat per ubicar la mercaderia.',
  tira=[[('eco','alegria','Les garrafes d\'aigua a dalt de tot, que a baix no hi caben!')],[('nexo','enfado','ECO! El que pesa, a baix. I el que més surt, a prop del moll i a l\'alçada de la cintura.')],[('eco','verguenza','D\'acord, d\'acord… baixo les garrafes.')]],
  cos='Per decidir on va cada producte es combinen diversos criteris:\n\n<b>Rotació</b>: el que surt més (productes A) va a prop de la zona d\'expedició i a l\'alçada entre la cintura i les espatlles, per recórrer menys i no ajupir-se. <b>Pes</b>: el que pesa, a baix; el lleuger, a dalt. <b>Volum</b>: el voluminós en ubicacions grans o a terra. <b>Fragilitat</b>: sense res de pesat a sobre i fora dels passos amb més trànsit. <b>Compatibilitat</b>: els aliments separats dels productes de neteja o químics, i els perillosos a la seva zona. <b>Conservació</b>: el refrigerat o congelat, a la cambra de fred.',
  ejemplo='A Palet, si col·loques el detergent a sobre de les galetes o el palet d\'aigua al nivell 3, la cap t\'ho farà notar… i si cau, hi ha trencament i accident.',
  errores=['Col·locar el que pesa als nivells alts.','Posar productes químics al costat d\'aliments.'],
  test=[('On hauria d\'anar un producte de molta rotació?',['Al fons del magatzem','A prop de l\'expedició i a una alçada còmoda','Al nivell més alt','A la cambra de fred'],1,'Així el recorregut i l\'esforç són menors.'),
   ('Quin producte hauria d\'anar al nivell més baix?',['Paquets de paper de cuina','Sacs de pinso de 25 kg','Caixes de bombetes','Caixes de mocadors'],1,'El que pesa, a baix.'),
   ('Quina combinació és incompatible?',['Arròs i pasta','Lleixiu i galetes','Aigua i suc','Llaunes i conserves'],1,'Els químics poden contaminar els aliments.'),
   ('Què cal evitar amb els productes fràgils?',['Etiquetar-los','Posar-hi pes a sobre','Ubicar-los en prestatgeria','Registrar-los'],1,'Es poden trencar.')])),

dict(slug='recepcion-documentacion-registro', id='A_recepcion', orden=4, codigos=['2.1', '2.5'], fase=1,
 es=dict(titulo='La recepción: pedido, albarán y registro', objetivo='Relacionar el pedido, el albarán y la factura y registrar la entrada de mercancía.',
  tira=[[('eco','alegria','¡Ha llegado el camión! Firmo el albarán y listo.')],[('nexo','esceptico','¿Sin contar las cajas? Si falta algo, ya has firmado que está todo.')],[('nexo','guino','Primero comprueba, después firma. Y anota lo que no cuadre.')]],
  cos='Tres documentos acompañan la compra: el <b>pedido</b> (lo que la empresa pidió al proveedor), el <b>albarán</b> (lo que el proveedor dice que entrega; lo firma quien recibe) y la <b>factura</b> (lo que hay que pagar). En la recepción se comprueba que el albarán coincide con el pedido y con lo que realmente llega.\n\nAl firmar el albarán, el almacén acepta la mercancía: si hay faltas o daños, hay que <b>anotarlo en el albarán</b> antes de firmar (reservas) y avisar al proveedor. Después se hace el <b>registro de entrada</b> en el sistema: referencia, cantidad, lote, fecha de caducidad, ubicación. Desde ese momento el stock está disponible para vender.',
  ejemplo='En Palet, en cada recepción tienes el albarán en pantalla. Si firmas sin revisar y faltaban dos cajas, el error será tuyo en el inventario.',
  errores=['Firmar el albarán sin haber contado ni revisado la mercancía.','Ubicar la mercancía sin registrarla: para el sistema no existe.'],
  test=[('¿Qué documento firma el almacén al recibir la mercancía?',['El pedido','El albarán','La factura','El inventario'],1,'Acredita la entrega.'),
   ('Faltan dos cajas. ¿Qué haces?',['Firmas y ya lo reclamarás','Anotas la falta en el albarán antes de firmar y avisas','Rechazas todo el camión','Lo apuntas en una libreta'],1,'Las reservas en el albarán son la prueba.'),
   ('¿Con qué documento se compara el albarán para saber si llega lo que se pidió?',['Con la factura','Con el pedido','Con el inventario anual','Con la carta de porte'],1,'El pedido es lo que se solicitó.'),
   ('¿Qué dato NO hace falta registrar en la entrada de un yogur?',['Lote','Fecha de caducidad','Cantidad','Precio de venta al público'],3,'El PVP es una decisión comercial, no de la recepción.')]),
 ca=dict(titulo='La recepció: comanda, albarà i registre', objetivo='Relacionar la comanda, l\'albarà i la factura i registrar l\'entrada de mercaderia.',
  tira=[[('eco','alegria','Ha arribat el camió! Signo l\'albarà i llestos.')],[('nexo','esceptico','Sense comptar les caixes? Si falta alguna cosa, ja has signat que hi és tot.')],[('nexo','guino','Primer comprova, després signa. I anota el que no quadri.')]],
  cos='Tres documents acompanyen la compra: la <b>comanda</b> (el que l\'empresa va demanar al proveïdor), l\'<b>albarà</b> (el que el proveïdor diu que lliura; el signa qui rep) i la <b>factura</b> (el que cal pagar). A la recepció es comprova que l\'albarà coincideix amb la comanda i amb el que arriba de debò.\n\nEn signar l\'albarà, el magatzem accepta la mercaderia: si hi ha faltes o danys, cal <b>anotar-ho a l\'albarà</b> abans de signar (reserves) i avisar el proveïdor. Després es fa el <b>registre d\'entrada</b> al sistema: referència, quantitat, lot, data de caducitat, ubicació. A partir d\'aquest moment l\'estoc està disponible per vendre.',
  ejemplo='A Palet, a cada recepció tens l\'albarà a la pantalla. Si signes sense revisar i faltaven dues caixes, l\'error serà teu a l\'inventari.',
  errores=['Signar l\'albarà sense haver comptat ni revisat la mercaderia.','Ubicar la mercaderia sense registrar-la: per al sistema no existeix.'],
  test=[('Quin document signa el magatzem en rebre la mercaderia?',['La comanda','L\'albarà','La factura','L\'inventari'],1,'Acredita el lliurament.'),
   ('Falten dues caixes. Què fas?',['Signes i ja ho reclamaràs','Anotes la falta a l\'albarà abans de signar i avises','Rebutges tot el camió','Ho apuntes en una llibreta'],1,'Les reserves a l\'albarà són la prova.'),
   ('Amb quin document es compara l\'albarà per saber si arriba el que es va demanar?',['Amb la factura','Amb la comanda','Amb l\'inventari anual','Amb la carta de port'],1,'La comanda és el que es va sol·licitar.'),
   ('Quina dada NO cal registrar a l\'entrada d\'un iogurt?',['Lot','Data de caducitat','Quantitat','Preu de venda al públic'],3,'El PVP és una decisió comercial, no de la recepció.')])),

dict(slug='control-recepcion-incidencias', id='A_control', orden=5, codigos=['2.2', '2.3'], fase=1,
 es=dict(titulo='Control de la mercancía e incidencias', objetivo='Hacer el control cuantitativo y cualitativo y decidir qué hacer con cada incidencia.',
  tira=[[('eco','sorpresa','Esta caja está aplastada y los yogures llegan a 12 °C…')],[('nexo','senalando','Daño y rotura de la cadena de frío: lo anotas y lo rechazas.')],[('eco','pensativo','Y si sobran cajas, ¿me las quedo?'),('nexo','paciencia','Tampoco: también es una incidencia.')]],
  cos='El <b>control cuantitativo</b> comprueba las cantidades: bultos, unidades, pesos. El <b>control cualitativo</b> comprueba el estado: embalaje intacto, producto correcto (referencia, formato), fecha de caducidad suficiente, temperatura de los refrigerados y congelados, etiquetado.\n\nIncidencias habituales: <b>faltas</b> (llega menos de lo que dice el albarán), <b>sobrantes</b> (llega más o algo no pedido), <b>daños o roturas</b>, <b>caducidad corta</b>, <b>temperatura incorrecta</b> y <b>referencia equivocada</b>. Según la empresa, se acepta con reservas, se rechaza esa parte o todo el envío, y siempre se comunica al proveedor y se deja constancia.',
  ejemplo='En Palet, en la recepción decides caja a caja: aceptar, aceptar con anotación o rechazar. Aceptar un producto en mal estado acabará en merma y en una bronca de la jefa.',
  errores=['Aceptar refrigerados sin medir la temperatura.','Quedarse los sobrantes sin comunicarlos.'],
  test=[('Contar los bultos y comprobar el peso es un control…',['Cualitativo','Cuantitativo','De calidad','Documental'],1,'Mide cantidades.'),
   ('Los yogures llegan a 11 °C. ¿Qué haces?',['Los aceptas y los pones rápido en la cámara','Anotas la incidencia y los rechazas','Los vendes con descuento','Los guardas en el almacén normal'],1,'Se ha roto la cadena de frío.'),
   ('Llega una caja más de lo que dice el albarán. Es…',['Una falta','Un sobrante','Una rotura','Un error de ubicación'],1,'También se comunica al proveedor.'),
   ('Un producto llega con fecha de caducidad muy próxima. ¿Qué tipo de control lo detecta?',['Cuantitativo','Cualitativo','De inventario','De expedición'],1,'Revisa el estado y las condiciones del producto.')]),
 ca=dict(titulo='Control de la mercaderia i incidències', objetivo='Fer el control quantitatiu i qualitatiu i decidir què fer amb cada incidència.',
  tira=[[('eco','sorpresa','Aquesta caixa està aixafada i els iogurts arriben a 12 °C…')],[('nexo','senalando','Dany i trencament de la cadena de fred: ho anotes i ho rebutges.')],[('eco','pensativo','I si sobren caixes, me les quedo?'),('nexo','paciencia','Tampoc: també és una incidència.')]],
  cos='El <b>control quantitatiu</b> comprova les quantitats: bults, unitats, pesos. El <b>control qualitatiu</b> comprova l\'estat: embalatge intacte, producte correcte (referència, format), data de caducitat suficient, temperatura dels refrigerats i congelats, etiquetatge.\n\nIncidències habituals: <b>faltes</b> (arriba menys del que diu l\'albarà), <b>sobrants</b> (arriba més o una cosa no demanada), <b>danys o trencaments</b>, <b>caducitat curta</b>, <b>temperatura incorrecta</b> i <b>referència equivocada</b>. Segons l\'empresa, s\'accepta amb reserves, es rebutja aquella part o tot l\'enviament, i sempre es comunica al proveïdor i se\'n deixa constància.',
  ejemplo='A Palet, a la recepció decideixes caixa a caixa: acceptar, acceptar amb anotació o rebutjar. Acceptar un producte en mal estat acabarà en merma i en una bronca de la cap.',
  errores=['Acceptar refrigerats sense mesurar la temperatura.','Quedar-se els sobrants sense comunicar-los.'],
  test=[('Comptar els bults i comprovar el pes és un control…',['Qualitatiu','Quantitatiu','De qualitat','Documental'],1,'Mesura quantitats.'),
   ('Els iogurts arriben a 11 °C. Què fas?',['Els acceptes i els poses ràpid a la cambra','Anotes la incidència i els rebutges','Els vens amb descompte','Els guardes al magatzem normal'],1,'S\'ha trencat la cadena de fred.'),
   ('Arriba una caixa més del que diu l\'albarà. És…',['Una falta','Un sobrant','Un trencament','Un error d\'ubicació'],1,'També es comunica al proveïdor.'),
   ('Un producte arriba amb data de caducitat molt propera. Quin tipus de control ho detecta?',['Quantitatiu','Qualitatiu','D\'inventari','D\'expedició'],1,'Revisa l\'estat i les condicions del producte.')])),

dict(slug='codificacion-etiquetado-trazabilidad', id='A_codigos', orden=6, codigos=['2.4', '8.2'], fase=1,
 es=dict(titulo='Códigos de barras, etiquetas y trazabilidad', objetivo='Interpretar los códigos EAN y GS1-128 y explicar para qué sirve la trazabilidad.',
  tira=[[('eco','confusion','8 41 23456 78901 2… ¿Es la lotería?')],[('nexo','guino','Es un EAN-13. El 84 es el prefijo de España. Y el último número comprueba que esté bien leído.')],[('eco','sorpresa','¡El código habla!')]],
  cos='El <b>EAN-13</b> es el código de barras de 13 dígitos de los productos de consumo: prefijo de la organización GS1 del país (84 para España), código de la empresa, código del producto y un <b>dígito de control</b> que detecta errores de lectura.\n\nEl <b>GS1-128</b> se usa en las unidades logísticas (cajas y palés) y puede llevar varios datos con <b>identificadores de aplicación</b>: código del artículo, <b>lote</b>, fecha de caducidad, cantidad o el <b>SSCC</b> (código único de 18 dígitos de cada palé). El <b>RFID</b> son etiquetas con chip que se leen por radiofrecuencia sin verlas.\n\nLa <b>trazabilidad</b> permite saber de dónde viene cada lote y a qué clientes ha ido. Es obligatoria en alimentación: si hay una alerta sanitaria, se retira solo el lote afectado.',
  ejemplo='En Palet, el lector de códigos te dice el lote y la caducidad de cada caja. Si un día hay una alerta por un lote de mayonesa, sabrás a qué tiendas ha ido.',
  errores=['Pensar que el EAN indica dónde se ha fabricado el producto: indica dónde se registró la empresa.','No registrar el lote: sin lote no hay trazabilidad.'],
  test=[('¿Qué prefijo GS1 corresponde a España?',['84','34','76','00'],0,'Las empresas registradas en GS1 España usan el 84.'),
   ('¿Para qué sirve el último dígito del EAN-13?',['Indica el precio','Es un dígito de control que detecta errores de lectura','Indica el país de fabricación','Es el número de lote'],1,'Se calcula a partir de los otros dígitos.'),
   ('¿Qué código identifica de forma única cada palé?',['EAN-13','SSCC (en GS1-128)','QR del producto','Código de ubicación'],1,'El SSCC tiene 18 dígitos y es único para cada unidad logística.'),
   ('Hay una alerta sanitaria por un lote de queso. ¿Qué permite la trazabilidad?',['Retirar solo ese lote y saber a qué clientes ha ido','Retirar todos los quesos del mercado','Cambiar el precio','Nada'],0,'Se localiza el lote exacto.')]),
 ca=dict(titulo='Codis de barres, etiquetes i traçabilitat', objetivo='Interpretar els codis EAN i GS1-128 i explicar per a què serveix la traçabilitat.',
  tira=[[('eco','confusion','8 41 23456 78901 2… És la loteria?')],[('nexo','guino','És un EAN-13. El 84 és el prefix d\'Espanya. I l\'últim número comprova que s\'hagi llegit bé.')],[('eco','sorpresa','El codi parla!')]],
  cos='L\'<b>EAN-13</b> és el codi de barres de 13 dígits dels productes de consum: prefix de l\'organització GS1 del país (84 per a Espanya), codi de l\'empresa, codi del producte i un <b>dígit de control</b> que detecta errors de lectura.\n\nEl <b>GS1-128</b> es fa servir a les unitats logístiques (caixes i palets) i pot portar diverses dades amb <b>identificadors d\'aplicació</b>: codi de l\'article, <b>lot</b>, data de caducitat, quantitat o l\'<b>SSCC</b> (codi únic de 18 dígits de cada palet). L\'<b>RFID</b> són etiquetes amb xip que es llegeixen per radiofreqüència sense veure-les.\n\nLa <b>traçabilitat</b> permet saber d\'on ve cada lot i a quins clients ha anat. És obligatòria en alimentació: si hi ha una alerta sanitària, es retira només el lot afectat.',
  ejemplo='A Palet, el lector de codis et diu el lot i la caducitat de cada caixa. Si un dia hi ha una alerta per un lot de maionesa, sabràs a quines botigues ha anat.',
  errores=['Pensar que l\'EAN indica on s\'ha fabricat el producte: indica on es va registrar l\'empresa.','No registrar el lot: sense lot no hi ha traçabilitat.'],
  test=[('Quin prefix GS1 correspon a Espanya?',['84','34','76','00'],0,'Les empreses registrades a GS1 Espanya fan servir el 84.'),
   ('Per a què serveix l\'últim dígit de l\'EAN-13?',['Indica el preu','És un dígit de control que detecta errors de lectura','Indica el país de fabricació','És el número de lot'],1,'Es calcula a partir dels altres dígits.'),
   ('Quin codi identifica de manera única cada palet?',['EAN-13','SSCC (en GS1-128)','QR del producte','Codi d\'ubicació'],1,'L\'SSCC té 18 dígits i és únic per a cada unitat logística.'),
   ('Hi ha una alerta sanitària per un lot de formatge. Què permet la traçabilitat?',['Retirar només aquell lot i saber a quins clients ha anat','Retirar tots els formatges del mercat','Canviar el preu','Res'],0,'Es localitza el lot exacte.')])),

dict(slug='transpale-manual-electrico', id='A_transpale', orden=7, codigos=['6.1'], fase=1,
 es=dict(titulo='El transpalé manual y eléctrico', objetivo='Usar el transpalé de forma segura y saber cuándo es mejor el eléctrico.',
  tira=[[('eco','alegria','¡Brum, brum! ¡Voy corriendo con el transpalé!')],[('nexo','enfado','¡Para! Con carga se va despacio, mirando hacia delante, y en rampa nunca la carga por delante bajando.')],[('eco','verguenza','Vale… sin carreras.')]],
  cos='El <b>transpalé</b> (o transpaleta) levanta el palé unos centímetros del suelo para moverlo horizontalmente. El <b>manual</b> se acciona con la fuerza del operario y sirve para distancias cortas y cargas moderadas; el <b>eléctrico</b> lleva motor, mueve más peso y más distancia con menos esfuerzo.\n\nNormas básicas: comprobar el estado antes de usarlo; no superar la <b>carga máxima</b> indicada; meter las horquillas hasta el fondo del palé y centrar la carga; circular despacio, con la carga baja y mirando el recorrido; en las rampas, ir con cuidado y nunca dejar que la carga empuje al operario; no transportar personas; dejarlo aparcado fuera de los pasillos con las horquillas bajadas.',
  ejemplo='En Palet empiezas con un transpalé manual: va lento con los palés pesados. Si corres por el pasillo o chocas con una estantería, la jefa lo verá.',
  errores=['Levantar un palé con las horquillas metidas a medias: la carga se desequilibra.','Dejar el transpalé en medio del pasillo con las horquillas levantadas.'],
  test=[('¿Para qué sirve el transpalé?',['Para subir palés a niveles altos','Para mover palés horizontalmente a ras de suelo','Para transportar personas','Para envolver palés'],1,'Solo los levanta unos centímetros.'),
   ('¿Cómo se deja aparcado el transpalé?',['En el pasillo, para tenerlo a mano','Fuera de los pasos y con las horquillas bajadas','Con las horquillas levantadas','Encima de un palé'],1,'Así nadie tropieza.'),
   ('¿Cuándo conviene el transpalé eléctrico?',['Para distancias largas y cargas pesadas','Para mover una caja pequeña','Para subir a un estante alto','Nunca'],0,'Reduce el esfuerzo del operario.'),
   ('Antes de levantar el palé hay que…',['Meter las horquillas hasta el fondo y centrar la carga','Ir rápido para ganar tiempo','Quitar el film','Pedir permiso al cliente'],0,'Así la carga va estable.')]),
 ca=dict(titulo='El transpalet manual i elèctric', objetivo='Fer servir el transpalet de manera segura i saber quan és millor l\'elèctric.',
  tira=[[('eco','alegria','Brrrum! Vaig corrents amb el transpalet!')],[('nexo','enfado','Para! Amb càrrega es va a poc a poc, mirant endavant, i a les rampes mai baixant amb la càrrega al davant.')],[('eco','verguenza','D\'acord… sense curses.')]],
  cos='El <b>transpalet</b> aixeca el palet uns centímetres del terra per moure\'l horitzontalment. El <b>manual</b> s\'acciona amb la força de l\'operari i serveix per a distàncies curtes i càrregues moderades; l\'<b>elèctric</b> porta motor, mou més pes i més distància amb menys esforç.\n\nNormes bàsiques: comprovar-ne l\'estat abans de fer-lo servir; no superar la <b>càrrega màxima</b> indicada; ficar les forquilles fins al fons del palet i centrar la càrrega; circular a poc a poc, amb la càrrega baixa i mirant el recorregut; a les rampes, anar amb compte i no deixar mai que la càrrega empenyi l\'operari; no transportar persones; deixar-lo aparcat fora dels passadissos amb les forquilles abaixades.',
  ejemplo='A Palet comences amb un transpalet manual: va lent amb els palets pesants. Si corres pel passadís o xoques amb una prestatgeria, la cap ho veurà.',
  errores=['Aixecar un palet amb les forquilles ficades a mitges: la càrrega es desequilibra.','Deixar el transpalet al mig del passadís amb les forquilles aixecades.'],
  test=[('Per a què serveix el transpalet?',['Per pujar palets a nivells alts','Per moure palets horitzontalment arran de terra','Per transportar persones','Per embolicar palets'],1,'Només els aixeca uns centímetres.'),
   ('Com es deixa aparcat el transpalet?',['Al passadís, per tenir-lo a mà','Fora dels passos i amb les forquilles abaixades','Amb les forquilles aixecades','A sobre d\'un palet'],1,'Així ningú no s\'hi entrebanca.'),
   ('Quan convé el transpalet elèctric?',['Per a distàncies llargues i càrregues pesants','Per moure una caixa petita','Per pujar a un prestatge alt','Mai'],0,'Redueix l\'esforç de l\'operari.'),
   ('Abans d\'aixecar el palet cal…',['Ficar les forquilles fins al fons i centrar la càrrega','Anar ràpid per guanyar temps','Treure el film','Demanar permís al client'],0,'Així la càrrega va estable.')])),

dict(slug='riesgos-manipulacion-manual-cargas', id='A_riesgos', orden=8, codigos=['7.1', '7.2'], fase=1,
 es=dict(titulo='Riesgos del almacén y manipulación manual de cargas', objetivo='Identificar los riesgos del almacén y levantar cargas con la técnica correcta.',
  tira=[[('eco','alegria','¡Esta caja la levanto con la espalda, sin doblar las piernas!')],[('nexo','enfado','Y mañana no te levantas de la cama. Piernas dobladas, espalda recta, carga pegada al cuerpo.')],[('eco','verguenza','Uf… vale.')]],
  cos='Riesgos habituales del almacén: <b>caídas</b> al mismo nivel (suelo mojado, objetos en el pasillo) y a distinto nivel (subirse a las estanterías), <b>caída de objetos</b> desde las estanterías, <b>golpes</b> y <b>atropellos</b> por carretillas y transpalés, <b>atrapamientos</b>, <b>sobreesfuerzos</b> e incendios.\n\n<b>Manipulación manual de cargas</b>: en general no se recomienda levantar más de <b>25 kg</b> (15 kg si se quiere proteger a la mayoría de trabajadores, incluidos jóvenes y personas con más riesgo). Técnica: acercarse a la carga, separar los pies, <b>doblar las piernas</b> manteniendo la <b>espalda recta</b>, coger bien la carga, levantarla con las piernas y llevarla <b>pegada al cuerpo</b>, sin girar el tronco. Si pesa demasiado, se usa una ayuda mecánica o se pide ayuda a un compañero.',
  ejemplo='En Palet, si tu personaje carga cajas pesadas a mano sin ayuda, acumula cansancio y aumenta el riesgo de lesión: mejor el transpalé.',
  errores=['Girar el tronco con la carga en los brazos.','Subirse a las estanterías para coger algo en lugar de usar una escalera o la carretilla.'],
  test=[('¿Qué peso máximo se recomienda en general para la manipulación manual?',['10 kg','25 kg','50 kg','No hay límite'],1,'Y 15 kg para proteger a la mayoría de trabajadores.'),
   ('¿Cuál es la técnica correcta?',['Piernas rectas y espalda doblada','Piernas dobladas, espalda recta y carga pegada al cuerpo','Levantar rápido con un tirón','Girar el tronco mientras levantas'],1,'La fuerza la hacen las piernas.'),
   ('Un charco de agua en el pasillo es un riesgo de…',['Caída al mismo nivel','Atrapamiento','Incendio','Caída a distinto nivel'],0,'Puede provocar resbalones.'),
   ('Subirse a la estantería para coger una caja del nivel 3 es…',['Correcto si vas con cuidado','Un riesgo de caída a distinto nivel: hay que usar los medios adecuados','Obligatorio','Más rápido y seguro'],1,'Las estanterías no son escaleras.')]),
 ca=dict(titulo='Riscos del magatzem i manipulació manual de càrregues', objetivo='Identificar els riscos del magatzem i aixecar càrregues amb la tècnica correcta.',
  tira=[[('eco','alegria','Aquesta caixa l\'aixeco amb l\'esquena, sense doblegar les cames!')],[('nexo','enfado','I demà no t\'aixeques del llit. Cames doblegades, esquena recta, càrrega enganxada al cos.')],[('eco','verguenza','Uf… d\'acord.')]],
  cos='Riscos habituals del magatzem: <b>caigudes</b> al mateix nivell (terra mullat, objectes al passadís) i a diferent nivell (pujar-se a les prestatgeries), <b>caiguda d\'objectes</b> des de les prestatgeries, <b>cops</b> i <b>atropellaments</b> per carretons i transpalets, <b>atrapaments</b>, <b>sobreesforços</b> i incendis.\n\n<b>Manipulació manual de càrregues</b>: en general no es recomana aixecar més de <b>25 kg</b> (15 kg si es vol protegir la majoria de treballadors, inclosos joves i persones amb més risc). Tècnica: acostar-se a la càrrega, separar els peus, <b>doblegar les cames</b> mantenint l\'<b>esquena recta</b>, agafar bé la càrrega, aixecar-la amb les cames i portar-la <b>enganxada al cos</b>, sense girar el tronc. Si pesa massa, es fa servir una ajuda mecànica o es demana ajuda a un company.',
  ejemplo='A Palet, si el teu personatge carrega caixes pesants a mà sense ajuda, acumula cansament i augmenta el risc de lesió: millor el transpalet.',
  errores=['Girar el tronc amb la càrrega als braços.','Pujar-se a les prestatgeries per agafar alguna cosa en lloc de fer servir una escala o el carretó.'],
  test=[('Quin pes màxim es recomana en general per a la manipulació manual?',['10 kg','25 kg','50 kg','No hi ha límit'],1,'I 15 kg per protegir la majoria de treballadors.'),
   ('Quina és la tècnica correcta?',['Cames rectes i esquena doblegada','Cames doblegades, esquena recta i càrrega enganxada al cos','Aixecar ràpid d\'una estrebada','Girar el tronc mentre aixeques'],1,'La força la fan les cames.'),
   ('Un bassal d\'aigua al passadís és un risc de…',['Caiguda al mateix nivell','Atrapament','Incendi','Caiguda a diferent nivell'],0,'Pot provocar relliscades.'),
   ('Pujar-se a la prestatgeria per agafar una caixa del nivell 3 és…',['Correcte si vas amb compte','Un risc de caiguda a diferent nivell: cal fer servir els mitjans adequats','Obligatori','Més ràpid i segur'],1,'Les prestatgeries no són escales.')])),
]
